class ArraySequence:
    def __init__(self, values):
        self.storage = list(values)
    def get(self, i):
        return self.storage[i]

class Node:
    def __init__(self, value, next_node=None):
        self.value, self.next = value, next_node

class LinkedSequence:
    def __init__(self, values):
        self.head = None
        for value in reversed(values):
            self.head = Node(value, self.head)
    def get(self, i):
        if i < 0:
            raise IndexError(i)
        node = self.head
        for _ in range(i):
            if node is None:
                raise IndexError(i)
            node = node.next
        if node is None:
            raise IndexError(i)
        return node.value

