def evaluate(tokens):
    stack = []
    for token in tokens:
        try:
            number = float(token)
        except ValueError:
            if len(stack) < 2:
                raise ValueError('Missing operand')
            right, left = stack.pop(), stack.pop()
            if token == '+':
                value = left + right
            elif token == '-':
                value = left - right
            elif token == '*':
                value = left * right
            elif token == '/':
                value = left / right
            else:
                raise ValueError('Unknown operator')
            stack.append(value)
        else:
            stack.append(number)
    if len(stack) != 1:
        raise ValueError('Extra values or empty expression')
    return stack.pop()
