# The map ADT promises key lookup, not numeric positional access.

class ChainedMap:
    def __init__(self, m=4):
        self.buckets = [[] for _ in range(m)]
    def bucket(self, key):
        return self.buckets[key % len(self.buckets)]
    def set(self, key, value):
        chain = self.bucket(key)
        for i, (k, _) in enumerate(chain):
            if k == key:
                chain[i] = (key, value)
                return
        chain.append((key, value))
    def get(self, key):
        for k, value in self.bucket(key):
            if k == key:
                return value
        raise KeyError(key)
    def delete(self, key):
        chain = self.bucket(key)
        for i, (k, _) in enumerate(chain):
            if k == key:
                del chain[i]
                return
        raise KeyError(key)
