def sift_down(a, size, i):
    while True:
        largest = i
        for child in (2*i+1, 2*i+2):
            if child < size and a[child] > a[largest]:
                largest = child
        if largest == i:
            return
        a[i], a[largest] = a[largest], a[i]
        i = largest
def heap_sort(a):
    for i in range(len(a)//2-1, -1, -1):
        sift_down(a, len(a), i)
    for end in range(len(a)-1, 0, -1):
        a[0], a[end] = a[end], a[0]
        sift_down(a, end, 0)
    return a
